# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="25" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">İSLAM\'IN ÇEVREYE BAKIŞI: KADER, ÖLÇÜ (MİZAN) VE EMANET (TDB.1.3.1)</text>\n  <rect x="20" y="42" width="320" height="175" rx="10" fill="#ecfdf5" stroke="#059669" stroke-width="2"/>\n  <text x="180" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#065f46">İLAHİ ÖLÇÜ (MİZAN) VE SÜNNETULLAH</text>\n  <text x="32" y="88" font-size="10.6" fill="#064e3b">• Sünnetullah: Allah\'ın evrende ve doğada koyduğu</text>\n  <text x="32" y="106" font-size="10.6" fill="#064e3b">  değişmez fiziksel ve biyolojik yasalar bütünüdür.</text>\n  <text x="32" y="128" font-size="10.6" fill="#064e3b">• Mizan ve Kader (Ölçü): Evrendeki her varlık hassas bir</text>\n  <text x="32" y="146" font-size="10.6" font-weight="bold" fill="#047857">  ekolojik denge ve ölçüyle yaratılmıştır (Kamer, 49).</text>\n  <text x="32" y="168" font-size="10.6" fill="#064e3b">• Rahmân 7-8: «Göğü yükseltti ve mizanı (dengeyi) koydu;</text>\n  <text x="32" y="186" font-size="10.6" font-weight="bold" fill="#047857">  sakın dengeyi bozmayın!»</text>\n  <rect x="360" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="520" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">HALİFE OLAN İNSANIN EMANET BİLİNCİ</text>\n  <text x="372" y="88" font-size="10.6" fill="#1e3a8a">• Hilafet ve İmar: İnsan yeryüzünün «halifesi» (Bakara, 30)</text>\n  <text x="372" y="106" font-size="10.6" fill="#1e3a8a">  ve imar edicisidir; doğanın sınırsız hâkimi değildir!</text>\n  <text x="372" y="128" font-size="10.6" fill="#1e3a8a">• Emanet Bilinci: Toprak, su, hava, bitkiler ve hayvanlar</text>\n  <text x="372" y="146" font-size="10.6" font-weight="bold" fill="#1d4ed8">  insana verilmiş ilahi birer emanettir.</text>\n  <text x="372" y="168" font-size="10.6" fill="#1e3a8a">• Rûm 41: «İnsanların kendi elleriyle yaptıkları yüzünden</text>\n  <text x="372" y="186" font-size="10.6" font-weight="bold" fill="#1d4ed8">  karada ve denizde fesat (bozulma) ortaya çıktı.»</text>\n  <rect x="20" y="224" width="660" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.2" font-weight="bold" fill="#1e293b">Tabiattaki her varlık Allah\'ın ayetidir ve O\'nu tesbih eder (İsrâ, 44); doğayı korumak kulluk görevidir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="25" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">PEYGAMBERİMİZİN SÜNNETİNDE ÇEVRE AHLAKI VE YEŞİL SEFERBERLİĞİ</text>\n  <rect x="20" y="42" width="320" height="175" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="180" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">AĞAÇLANDIRMA VE KORUMA BÖLGELERİ (HIMA)</text>\n  <text x="32" y="88" font-size="10.6" fill="#78350f">• Kıyamet Hadisi: «Kıyametin kopacağını bilseniz bile</text>\n  <text x="32" y="106" font-size="10.6" font-weight="bold" fill="#92400e">  elinizdeki fidanı dikiniz!» (Ahmed b. Hanbel).</text>\n  <text x="32" y="128" font-size="10.6" fill="#78350f">• Sadaka-i Câriye: Dikilen ağaçtan insanın, kuşun ve</text>\n  <text x="32" y="146" font-size="10.6" fill="#78350f">  hayvanın yediği her meyve diken için sadakadır.</text>\n  <text x="32" y="168" font-size="10.6" font-weight="bold" fill="#92400e">• Hıma ve Harem Uygulaması: Medine, Mekke ve Tâif</text>\n  <text x="32" y="186" font-size="10.4" fill="#78350f">  çevresini ağaç kesimi ve avlanmanın yasak olduğu «milli park» ilan etti.</text>\n  <rect x="360" y="42" width="320" height="175" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="520" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">HAYVAN HAKLARI VE MERHAMET İLKELERİ</text>\n  <text x="372" y="88" font-size="10.6" fill="#581c87">• En\'âm 38: Hayvanlar da tıpkı insanlar gibi birer «ümmet»</text>\n  <text x="372" y="106" font-size="10.6" fill="#581c87">  (topluluk) olarak yaratılmıştır.</text>\n  <text x="372" y="128" font-size="10.6" fill="#581c87">• Hayvanlara taşıyamayacağı yük yüklemeyi, aç bırakmayı,</text>\n  <text x="372" y="146" font-size="10.6" fill="#581c87">  dövüştürmeyi, nişan tahtası yapmayı ve yuvalarını</text>\n  <text x="372" y="164" font-size="10.6" font-weight="bold" fill="#6b21a8">  bozmayı kesin olarak yasaklamıştır.</text>\n  <text x="372" y="184" font-size="10.5" fill="#581c87">• Susuz köpeğe su veren günahkâr bağışlanmış, kediyi</text>\n  <text x="372" y="200" font-size="10.5" fill="#581c87">  aç bırakan ise azaba müstahak olmuştur.</text>\n  <rect x="20" y="224" width="660" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.2" font-weight="bold" fill="#1e293b">Savaş hukukunda bile meyve ağaçlarının kesilmesi, ekinlerin yakılması ve hayvanların öldürülmesi yasaklanmıştır.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="25" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">DOĞAL KAYNAKLARIN KORUNMASI: İSRAF YASAĞI, SU VE TEMİZLİK</text>\n  <rect x="20" y="42" width="320" height="175" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="180" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#9a3412">SU TASARRUFU VE İSRAF YASAĞI</text>\n  <text x="32" y="88" font-size="10.6" fill="#7c2d12">• Enbiyâ 30: «Canlı olan her şeyi sudan yarattık.»</text>\n  <text x="32" y="108" font-size="10.6" fill="#7c2d12">• A\'râf 31: «Yiyiniz, içiniz fakat israf etmeyiniz!»</text>\n  <text x="32" y="128" font-size="10.6" fill="#7c2d12">• Peygamberimiz abdest alırken suyu çok kullanan</text>\n  <text x="32" y="146" font-size="10.6" fill="#7c2d12">  Sa\'d b. Ebî Vakkâs\'ı uyarmıştır:</text>\n  <text x="32" y="166" font-size="10.6" font-weight="bold" fill="#9a3412">  «Akan bir nehrin kenarında olsan bile suyu israf etme!»</text>\n  <text x="32" y="186" font-size="10.5" fill="#7c2d12">• İktisat (tutumluluk) ve kanaat, çevre ahlakının özüdür.</text>\n  <rect x="360" y="42" width="320" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">ÇEVRE TEMİZLİĞİ VE KUL HAKKI</text>\n  <text x="372" y="88" font-size="10.6" fill="#14532d">• «Temizlik imanın yarısıdır» (Müslim, Tahâret, 1).</text>\n  <text x="372" y="108" font-size="10.6" fill="#14532d">• Yol üzerindeki eziyet verici bir engeli (taşı, dikeni, çöpü)</text>\n  <text x="372" y="126" font-size="10.6" font-weight="bold" fill="#15803d">  kaldırmak imanın şubelerinden ve sadakadandır.</text>\n  <text x="372" y="148" font-size="10.6" fill="#14532d">• Durgun ve akan suları, insanların yürüdüğü yolları ve</text>\n  <text x="372" y="166" font-size="10.6" fill="#14532d">  dinlendiği ağaç gölgelerini kirletmek «lanet sebebi»</text>\n  <text x="372" y="184" font-size="10.6" font-weight="bold" fill="#15803d">  ve «kamu (kul) hakkı ihlali» sayılmıştır.</text>\n  <rect x="20" y="224" width="660" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.2" font-weight="bold" fill="#1e293b">İslam medeniyetinde leylek vakıflarından kuş evlerine kadar çevre ve hayvan sevgisi kurumsallaşmıştır.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
